import{_ as r,o,c as a,ag as l}from"./chunks/framework.D2veAa-g.js";const b=JSON.parse('{"title":"架构师-备考 论文写作-专题论点参考","description":"","frontmatter":{"title":"架构师-备考 论文写作-专题论点参考"},"headers":[],"relativePath":"论文写作/专题论点参考.md","filePath":"论文写作/专题论点参考.md","lastUpdated":null}'),e={name:"论文写作/专题论点参考.md"};function d(n,t,i,s,h,g){return o(),a("div",null,[...t[0]||(t[0]=[l('<h2 id="考点清单" tabindex="-1">考点清单 <a class="header-anchor" href="#考点清单" aria-label="Permalink to &quot;考点清单&quot;">​</a></h2><ul><li>[x] 软件分析与设计（OOA/OOD）论文写作框架</li><li>[x] 软件测试论文论点（自动化测试融合三趋势）</li><li>[x] 云原生架构概念与演进</li><li>[x] 解释器架构风格要点</li><li>[x] 软件架构评估（ATAM）论文要点</li></ul><h2 id="笔记" tabindex="-1">笔记 <a class="header-anchor" href="#笔记" aria-label="Permalink to &quot;笔记&quot;">​</a></h2><h3 id="一、软件分析与设计论文" tabindex="-1">一、软件分析与设计论文 <a class="header-anchor" href="#一、软件分析与设计论文" aria-label="Permalink to &quot;一、软件分析与设计论文&quot;">​</a></h3><blockquote><p>核心区分：<strong>分析 = &quot;做什么&quot;（What）</strong>；<strong>设计 = &quot;怎么做&quot;（How）</strong>。</p></blockquote><table tabindex="0"><thead><tr><th>维度</th><th>软件分析（OOA）</th><th>软件设计（OOD）</th></tr></thead><tbody><tr><td>核心问题</td><td>做什么？</td><td>怎么做？</td></tr><tr><td>关注点</td><td>精确化用户需求，问题域模型</td><td>解决方案蓝图，软件系统构造</td></tr><tr><td>输出</td><td>需求规格说明书、用例模型、分析模型（概念层）</td><td>设计规格说明书、架构设计、详细设计（实现层）</td></tr><tr><td>视角</td><td>业务视角，与实现技术无关</td><td>技术视角，关联实现技术</td></tr></tbody></table><h4 id="ooa-论文第三点写作框架" tabindex="-1">OOA 论文第三点写作框架 <a class="header-anchor" href="#ooa-论文第三点写作框架" aria-label="Permalink to &quot;OOA 论文第三点写作框架&quot;">​</a></h4><ol><li><strong>用例建模</strong>：识别参与者和核心用例，绘制用例图</li><li><strong>领域建模</strong>：识别名词找概念类，分析静态关系，绘制概念类图</li><li><strong>动态建模</strong>：选取核心用例，用序列图/活动图分析实现过程</li><li><strong>总结</strong>：分析模型为后续设计和开发提供清晰蓝图</li></ol><h4 id="ood-论文第三点写作框架" tabindex="-1">OOD 论文第三点写作框架 <a class="header-anchor" href="#ood-论文第三点写作框架" aria-label="Permalink to &quot;OOD 论文第三点写作框架&quot;">​</a></h4><ol><li><strong>架构设计</strong>：系统划分（分层/微服务），绘制组件图</li><li><strong>详细设计</strong>： <ul><li>模式应用：用了哪些设计模式（如工厂解耦创建、策略封装算法族），为什么用、怎么用</li><li>接口设计：核心模块接口定义</li><li>数据设计：核心数据库表结构</li></ul></li><li><strong>总结</strong>：良好设计带来的高可扩展性、可维护性</li></ol><h4 id="设计四层次" tabindex="-1">设计四层次 <a class="header-anchor" href="#设计四层次" aria-label="Permalink to &quot;设计四层次&quot;">​</a></h4><p>架构设计（子系统划分/架构风格）→ 接口设计（API 规范）→ 过程设计（算法/业务流程）→ 数据设计（ER 图/缓存策略）。</p><hr><h3 id="二、软件测试论文-★" tabindex="-1">二、软件测试论文 ★ <a class="header-anchor" href="#二、软件测试论文-★" aria-label="Permalink to &quot;二、软件测试论文 ★&quot;">​</a></h3><blockquote><p>题目：论软件系统测试方法及应用。</p></blockquote><p><strong>论文论点 — 传统测试与自动化测试融合三趋势：</strong></p><table tabindex="0"><thead><tr><th>趋势</th><th>内容</th></tr></thead><tbody><tr><td><strong>分层协作</strong></td><td>构建测试金字塔：底层大量单元测试（高度自动化）→ 中层集成测试+API 测试（自动化为主）→ 顶层少量 UI 端到端测试（自动化+手动探索性结合）</td></tr><tr><td><strong>智能赋能</strong></td><td>引入 AI 与数据驱动（如 AI 生成测试用例、大模型写单元测试）</td></tr><tr><td><strong>全过程集成</strong></td><td>自动化测试套件集成到 CI/CD 流水线，每次提交自动触发测试并获得即时反馈，&quot;开发-测试-部署&quot;闭环</td></tr></tbody></table><p><strong>论文实践要点：</strong></p><table tabindex="0"><thead><tr><th>测试类型</th><th>工具/方法</th></tr></thead><tbody><tr><td>单元测试</td><td>Sonar 代码扫描 + 测试覆盖率，路径覆盖</td></tr><tr><td>自动化测试</td><td>Jenkins/GitLab CI 对接</td></tr><tr><td>性能测试</td><td>JMeter 压测模拟线上高峰</td></tr><tr><td>AI 测试</td><td>大模型生成用例</td></tr></tbody></table><p><strong>项目实际流程参考</strong>：提测 → 测试人员编写测试用例 → 测试自动化脚本 → 开发人员单元测试 → Sonar 代码扫描 + 覆盖率 → 质量保障。</p><hr><h3 id="三、云原生架构" tabindex="-1">三、云原生架构 <a class="header-anchor" href="#三、云原生架构" aria-label="Permalink to &quot;三、云原生架构&quot;">​</a></h3><blockquote><p>云原生 = 容器化 + 微服务 + 持续交付 + 动态编排，构建可弹性扩展、故障自愈且高效利用云资源的应用体系。</p></blockquote><p><strong>演进路径</strong>：传统单体（业务代码+非功能代码混合）→ 早期分布式（服务拆分但非功能代码仍由应用实现）→ <strong>云原生</strong>（云设施接管非功能需求：弹性/韧性/安全/可观测性）。</p><p><strong>核心目标</strong>：开发者只关注业务逻辑，获得轻量、敏捷、高度自动化的交付与运维能力。</p><hr><h3 id="四、解释器架构风格" tabindex="-1">四、解释器架构风格 <a class="header-anchor" href="#四、解释器架构风格" aria-label="Permalink to &quot;四、解释器架构风格&quot;">​</a></h3><p><strong>核心组成</strong>：解释引擎 + 代码存储区 + 工作状态数据结构 + 执行进度数据结构。</p><p><strong>基于规则的系统</strong>：规则集 + 规则解释器 + 规则/数据选择器 + 工作内存。</p><p><strong>特点：</strong></p><ul><li>系统核心是虚拟机</li><li>可用多种操作解释一个句子，灵活应对自定义场景</li><li>适合特定领域、模式匹配系统与语言编译器</li></ul><hr><h3 id="五、软件架构评估-atam-论文" tabindex="-1">五、软件架构评估（ATAM）论文 <a class="header-anchor" href="#五、软件架构评估-atam-论文" aria-label="Permalink to &quot;五、软件架构评估（ATAM）论文&quot;">​</a></h3><p><strong>ATAM（架构权衡分析法）</strong> 是架构评估的主流方法，核心工具是<strong>效用树</strong>。</p><p><strong>论文结构建议：</strong></p><ol><li>项目背景 + 架构评估必要性</li><li>ATAM 方法概述（效用树、场景分类、敏感点/权衡点）</li><li>评估实施过程（质量属性效用树构建、场景优先级排序、架构分析与权衡）</li><li>评估结果与架构改进</li></ol><p><strong>ATAM 关键概念：</strong></p><ul><li><strong>效用树</strong>：树根（质量目标）→ 质量属性 → 属性分类 → 质量属性场景（叶子）</li><li><strong>3 种场景</strong>：用例场景/增长场景/探索性场景</li><li><strong>敏感点</strong> vs <strong>权衡点</strong>：敏感点影响单个质量属性，权衡点影响多个</li></ul>',38)])])}const p=r(e,[["render",d]]);export{b as __pageData,p as default};
